internal static class CalibratorRuntime {
    internal const string Version="0.1.4";
    internal static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=1048576};
    internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
    internal static string Native(string name,string expected){
        string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FPVCalibrador","Runtime",expected.Substring(0,16));Directory.CreateDirectory(root);string path=Path.Combine(root,name);
        if(File.Exists(path)){if(Hash(File.ReadAllBytes(path))!=expected)throw new IOException("Biblioteca local divergente: "+name);return path;}
        using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Calibrator."+name)){
            if(stream==null)throw new IOException("Biblioteca ausente no executável: "+name);using(var memory=new MemoryStream()){stream.CopyTo(memory);byte[] bytes=memory.ToArray();if(Hash(bytes)!=expected)throw new IOException("Biblioteca embutida divergente.");using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);}}
        }return path;
    }
    internal static CalibratorGamepad Gamepad(){return new CalibratorGamepad(Native("SDL3.dll","eb4c055ba3a974ee81414e8b357afa2de35a00336d29b2bd944a460e6dfd00c8"),Native("ViGEmClient.dll","00303f99e1968d523fbd08a7c691d60d145b7335059ec593947841d124c10875"));}
    internal static void WriteJson(string path,object data){File.WriteAllText(path,Json.Serialize(data),new UTF8Encoding(false));}
    internal static string Notices(){var output=new StringBuilder("Calibrador FPV "+Version+"\r\n\r\nNão altera mods, drivers, saves ou configurações dos jogos.\r\nVídeo AVI MJPEG30fps sem áudio; timestamps reais e duplicações ficam no CSV.\r\n\r\n");foreach(string name in new[]{"ViGEm-LICENSE.txt","SDL-LICENSE.txt"})using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("Calibrator."+name))if(s!=null)using(var r=new StreamReader(s))output.AppendLine(r.ReadToEnd());return output.ToString();}
}

internal static class CalibratorWindows {
    [StructLayout(LayoutKind.Sequential)] internal struct Rect {public int Left,Top,Right,Bottom;}
    [StructLayout(LayoutKind.Sequential)] internal struct Point {public int X,Y;}

    [DllImport("user32.dll")] internal static extern uint GetWindowThreadProcessId(IntPtr window,out uint pid);
    [DllImport("user32.dll")] static extern bool GetClientRect(IntPtr window,out Rect rect);
    [DllImport("user32.dll")] static extern bool ClientToScreen(IntPtr window,ref Point point);
    [DllImport("user32.dll",SetLastError=true)] internal static extern bool RegisterHotKey(IntPtr window,int id,uint modifiers,uint key);
    [DllImport("user32.dll")] internal static extern bool UnregisterHotKey(IntPtr window,int id);

    delegate bool WindowCallback(IntPtr window,IntPtr parameter);
    [DllImport("user32.dll")] static extern bool EnumWindows(WindowCallback callback,IntPtr parameter);
    [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr window);

    [DllImport("user32.dll")] static extern bool SetProcessDPIAware();
    internal static void Dpi(){try{SetProcessDPIAware();}catch(EntryPointNotFoundException){}}
    internal static bool Allowed(string process){return process=="Cyberpunk2077"||process=="Uncrashed"||process=="Uncrashed-Win64-Shipping";}
    internal static bool MatchesGame(string process,int game){return game==0?(process=="Uncrashed"||process=="Uncrashed-Win64-Shipping"):game==1&&process=="Cyberpunk2077";}
    internal static IntPtr FindGame(int game){IntPtr found=IntPtr.Zero;long largest=0;EnumWindows((w,p)=>{try{if(!IsWindowVisible(w))return true;using(var proc=Process.GetProcessById(Pid(w))){if(!MatchesGame(proc.ProcessName,game))return true;Rectangle area=Area(w);long size=(long)area.Width*area.Height;if(size>largest){found=w;largest=size;}}}catch{}return true;},IntPtr.Zero);if(found==IntPtr.Zero)throw new IOException((game==0?"Uncrashed":"Cyberpunk")+" não foi encontrado em uma janela disponível.");return found;}

    internal static int Pid(IntPtr window){uint pid;GetWindowThreadProcessId(window,out pid);return (int)pid;}

    internal static Rectangle Area(IntPtr window){Rect r;var p=new Point();if(!GetClientRect(window,out r)||!ClientToScreen(window,ref p)||r.Right<100||r.Bottom<100)throw new IOException("A janela do jogo não está disponível para captura.");return new Rectangle(p.X,p.Y,r.Right,r.Bottom);}
    internal static Rectangle CenterCrop(Rectangle area){int width=Math.Min(960,area.Width),height=Math.Min(540,area.Height);return new Rectangle(area.Left+(area.Width-width)/2,area.Top+(area.Height-height)/2,width,height);}
    // shortcut: captures visible screen pixels; use window capture if occluded-window recording is needed.
    internal static Bitmap Frame(IntPtr window,int pid){if(window==IntPtr.Zero||Pid(window)!=pid)throw new IOException("A janela escolhida foi fechada ou mudou de processo.");Rectangle area=CenterCrop(Area(window));var frame=new Bitmap(area.Width,area.Height,PixelFormat.Format24bppRgb);try{using(var g=Graphics.FromImage(frame))g.CopyFromScreen(area.Location,System.Drawing.Point.Empty,area.Size,CopyPixelOperation.SourceCopy);return frame;}catch{frame.Dispose();throw;}}
    internal static Size VideoSize(Rectangle area){double scale=Math.Min(1,Math.Min(1280.0/area.Width,720.0/area.Height));return new Size(Math.Max(2,(int)(area.Width*scale)/2*2),Math.Max(2,(int)(area.Height*scale)/2*2));}
}


internal sealed class CalibratorClip : IDisposable {
    readonly CalibratorCapture writer;readonly IntPtr window;readonly int pid;readonly ManualResetEvent stop=new ManualResetEvent(false);readonly Thread worker;readonly Stopwatch clock;
    internal readonly double StartedClockSeconds;
    volatile string annotation="";internal string Error;internal long Frames,Duplicates;internal bool Done;
    internal CalibratorClip(string directory,IntPtr target,int targetPid,Stopwatch masterClock){clock=masterClock;StartedClockSeconds=clock.Elapsed.TotalSeconds;window=target;pid=targetPid;Directory.CreateDirectory(directory);Rectangle full=CalibratorWindows.Area(window),crop=CalibratorWindows.CenterCrop(full);Size size=CalibratorWindows.VideoSize(crop);CalibratorRuntime.WriteJson(Path.Combine(directory,"geometry.json"),new{ClientWidth=full.Width,ClientHeight=full.Height,CropX=crop.Left-full.Left,CropY=crop.Top-full.Top,CropWidth=crop.Width,CropHeight=crop.Height,VideoWidth=size.Width,VideoHeight=size.Height,StartedClockSeconds=StartedClockSeconds});writer=new CalibratorCapture(directory,size.Width,size.Height,30);worker=new Thread(Work){IsBackground=true,Name="FPV screen recorder"};worker.Start();}
    internal void Label(string value){annotation=value;}
    void Work(){try{double next=0;while(!stop.WaitOne(0)){using(var image=CalibratorWindows.Frame(window,pid))writer.AddFrame(image,clock.Elapsed.TotalSeconds-StartedClockSeconds,annotation);next+=1.0/30;int wait=(int)Math.Max(0,(next-(clock.Elapsed.TotalSeconds-StartedClockSeconds))*1000);if(wait>0)stop.WaitOne(wait);}}catch(Exception ex){Error=ex.Message;}finally{try{writer.Complete();Frames=writer.Frames;Duplicates=writer.DuplicatedFrames;}catch(Exception ex){Error=ex.Message;}Done=true;}}
    public void Dispose(){stop.Set();if(!worker.Join(5000))throw new IOException("A gravação ainda está terminando. Aguarde antes de fechar.");stop.Dispose();writer.Dispose();}
}

