    void Confirm(){if(sequence==null)throw new IOException("Inicie a série com F10 primeiro.");if(pad==null||!pad.Connected)throw new IOException("DualSense desconectado.");if(sequence.State!="Waiting"&&sequence.State!="RunningVertical")return;manualInput=false;manualPending=false;SendReport(new ControlSample());last=pad.ReadPhysical();sequence.Confirm(clock.Elapsed.TotalSeconds,last);Event("confirm",last,new ControlSample());}
    void Poll(){if(working||closing||handoff)return;working=true;try{if(pad==null)return;if(!pad.Connected){manualInput=false;manualPending=false;pad.DisconnectVirtual();if(sequence!=null&&(sequence.Recording||sequence.State=="Preparing"))Stop("Controle físico desconectado.");return;}last=pad.ReadPhysical();TryManual(last);ControlSample sent=manualInput?last.Copy():new ControlSample();if(sequence!=null){var automatic=sequence.Tick(clock.Elapsed.TotalSeconds,last,false);if(!manualInput)sent=automatic;}
        // Release overrides before any recording finalization or disk I/O can block.
        if(pad.VirtualConnected)SendReport(sent);if(sequence!=null){bool captureNow=sequence.Recording||sequence.State=="Preparing";if(captureNow&&clip==null)StartClip();if(!captureNow&&clip!=null)EndClip();if(sequence.State!=lastState){if(sequence.State=="Waiting"&&lastState.StartsWith("Running",StringComparison.Ordinal))System.Media.SystemSounds.Asterisk.Play();lastState=sequence.State;Event("state",last,sent);}if(sequence.Complete||sequence.State=="Aborted"){if(clip!=null)EndClip();CloseLog();if(sequence.Complete){FinishGame();hud.UpdateFor(target,GameName(selectedGame).ToUpperInvariant()+" — CONCLUÍDO",status.Text);return;}}if(clip!=null&&clip.Error!=null)throw new IOException(clip.Error);status.Text=StageTitle(selectedGame,sequence.StepIndex,sequence.StepCount)+"\r\n"+sequence.Status+(manualInput?" MANUAL ativo.":" Potência automática/zero.");}
        if(sequence!=null&&!sequence.Complete&&sequence.State!="Aborted")hud.UpdateFor(target,StageTitle(selectedGame,sequence.StepIndex,sequence.StepCount),sequence.Status+(manualInput?" MANUAL ativo.":" Potência automática/zero."));else hud.Hide();
        if(clip!=null)clip.Label(targetName+" | "+sequence.ClipName+" | "+sequence.Status+" | "+AxisText(sent));if(log!=null&&clock.Elapsed.TotalSeconds-lastLog>=.01){Event("sample",last,sent);lastLog=clock.Elapsed.TotalSeconds;}if(++ticks%12==0){axes.Text="DualSense físico: "+AxisText(last)+"\r\nXbox enviado: "+(pad.VirtualConnected?AxisText(lastSent):"desconectado");padInfo.Text=!pad.VirtualConnected?"Xbox virtual desconectado.":manualInput?"CALIBRAÇÃO / MANUAL LIBERADO — o Xbox acompanha seus sticks.":manualPending?"AGUARDANDO STICK ESQUERDO NO MÍNIMO — depois libera automaticamente.":"POTÊNCIA AUTOMÁTICA / ZERO — para calibrar, clique em Liberar calibração.";}}
        catch(Exception ex){Fail(ex);}finally{working=false;}}
    internal static string StageTitle(int game,int step,int total){return GameName(game).ToUpperInvariant()+" — ETAPA "+step+" DE "+total;} static string AxisText(ControlSample a){return String.Format(CultureInfo.InvariantCulture,"Aceleração {0:P0} · Yaw {1:F2} · Roll {2:F2} · Pitch {3:F2}",a.Throttle,a.Yaw,a.Roll,a.Pitch);}
    void StartClip(){clipName=sequence.ClipName;string directory=Path.Combine(session,clipName);clip=new CalibratorClip(directory,target,targetPid,clock);clips.Add(clipName);Event("record.start",last,lastSent);}
    void EndClip(){var current=clip;clip=null;if(current==null)return;current.Dispose();Event("record.stop",last,lastSent);CalibratorRuntime.WriteJson(Path.Combine(session,clipName,"capture.json"),new{StartedClockSeconds=current.StartedClockSeconds,Frames=current.Frames,DuplicatedFrames=current.Duplicates,Error=current.Error,Game=targetName,Clip=clipName,Finished=DateTimeOffset.Now.ToString("o")});if(current.Error!=null)throw new IOException("Falha na gravação: "+current.Error);}
    void Event(string kind,ControlSample physical,ControlSample sent){if(log==null)return;log.WriteLine(String.Join(",",new[]{clock.Elapsed.TotalSeconds.ToString("F6",CultureInfo.InvariantCulture),kind,sequence==null?"":sequence.State,kind.StartsWith("record.",StringComparison.Ordinal)?clipName:sequence==null?"":sequence.ClipName,physical.Throttle.ToString("R",CultureInfo.InvariantCulture),physical.Yaw.ToString("R",CultureInfo.InvariantCulture),physical.Roll.ToString("R",CultureInfo.InvariantCulture),physical.Pitch.ToString("R",CultureInfo.InvariantCulture),sent.Throttle.ToString("R",CultureInfo.InvariantCulture),sent.Yaw.ToString("R",CultureInfo.InvariantCulture),sent.Roll.ToString("R",CultureInfo.InvariantCulture),sent.Pitch.ToString("R",CultureInfo.InvariantCulture)}));log.Flush();}
    void Stop(string reason){LockMode(false);if(sequence!=null)sequence.Abort(reason);manualInput=false;manualPending=false;hud.Hide();if(pad!=null&&pad.VirtualConnected){if(pad.Connected)SendReport(new ControlSample());else pad.DisconnectVirtual();}try{EndClip();}finally{CloseLog();}status.Text=reason+" Potência bloqueada em zero. F4 solicita calibração; depois leve o stick esquerdo ao mínimo uma vez.";}
    void CloseLog(){if(log==null)return;log.Dispose();log=null;}
    void Fail(Exception ex){try{Stop(ex.Message);}catch{}status.Text=ex.Message;}
    void Photo(){if(sequence!=null&&(sequence.Recording||sequence.State=="Preparing"))throw new IOException("Use F11 antes da prévia.");int mode=sequence!=null&&!sequence.Complete&&sequence.State!="Aborted"?selectedGame:(cyberpunkMode.Checked?1:0);ChooseGame(mode);string folder=NewFolder(targetName+"-foto");using(var frame=CalibratorWindows.Frame(target,targetPid))frame.Save(Path.Combine(folder,"teste.png"),ImageFormat.Png);output.Text=folder;status.Text="Prévia salva para "+GameName(mode)+". Confira o recorte antes do ensaio.";}
    static string RootFolder(){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"FPV Calibrador");}
    static string NewFolder(string name){string root=Path.Combine(RootFolder(),DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+name+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(root);return root;}
    void OpenFolder(){string root=RootFolder();Directory.CreateDirectory(root);Process.Start(new ProcessStartInfo{FileName=root,UseShellExecute=true});}
    static object SavedProfile(){try{string root=@"C:\Program Files (x86)\Steam\steamapps\common\Cyberpunk 2077\bin\x64\plugins\cyber_engine_tweaks\mods\FPVDrone";var index=CalibratorRuntime.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"FPVDrone_Profiles.json")));string path=Path.GetFullPath(Path.Combine(root,Convert.ToString(index["activePath"])));if(!path.StartsWith(root+"\\profiles\\",StringComparison.OrdinalIgnoreCase)||!path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)||new FileInfo(path).Length>262144)return null;var data=CalibratorRuntime.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var physics=(Dictionary<string,object>)data["physics"];var controls=(Dictionary<string,object>)data["controls"];var camera=(Dictionary<string,object>)data["camera"];return new{Profile=Path.GetFileName(path),Rates=controls["actualRates"],Gravity=physics["gravity"],Mass=physics["massGrams"],MotorReference=((Dictionary<string,object>)physics["powerSystem"])["referenceThrustToWeightRatio"],CameraAngle=camera["angle"],CameraFov=camera["horizontalFOV"],SavedOnly=true};}catch{return null;}}
    void Help(){using(var form=new Form{Text="Como usar e licenças",Width=820,Height=650,StartPosition=FormStartPosition.CenterParent}){var text=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Text="PREPARAÇÃO\r\n1. Ler DualSense e conectar Xbox virtual. Os eixos começam zerados. Se já calibrado, mantenha o perfil do Xbox no jogo.\r\n2. Clique em Liberar calibração (F4) e depois leve o stick esquerdo totalmente para baixo uma vez. O app libera automaticamente; pode soltar e mover todos os eixos. Confira as linhas DualSense físico e Xbox enviado. F5 volta a zero. ARM é manual, sem L1 automático.\r\n3. Escolha Uncrashed ou Cyberpunk. Deixe somente esse jogo pronto para voar em Acro, perto do chão/nivelado. Mantenha o outro pausado. F6 salva prévia central 960×540.\r\n\r\nTESTE\r\n4. F10 inicia o modo escolhido: potência zero por 1 s e depois subida a 100%. Não há confirmação extra nem verificação de foco.\r\n5. No teste vertical, F10 após o impacto termina o trecho. Entre etapas, reposicione/reset; F10 continua. A potência fica em zero enquanto espera.\r\n6. F11 interrompe em zero. Desconexão física e erro de gravação também interrompem.\r\n7. Ao terminar, o modo encerra; o aplicativo não envia Esc, não troca nem pausa jogos. Escolha o outro modo para uma sessão separada.\r\n8. Mantenha o jogo visível: a gravação usa pixels do recorte da tela, podendo registrar uma janela que o cubra. O controle virtual pode ser recebido pelos dois jogos; deixe o outro pausado.\r\n\r\nSaída em Documentos > FPV Calibrador > Serie-Uncrashed ou Serie-Cyberpunk. Envie AVI/CSV/JSON para análise; são comandos enviados, não telemetria nem detecção automática de impacto.\r\n\r\n"+CalibratorRuntime.Notices()};form.Controls.Add(text);form.ShowDialog(this);}}
}

internal static class CalibratorProgram {
    [STAThread]static int Main(string[] args){CalibratorWindows.Dpi();try{
        if(args.Length==2&&args[0]=="--self-test"){Directory.CreateDirectory(args[1]);int capture=CalibratorCapture.SelfTest(Path.Combine(args[1],"capture"));int sequence=CalibratorSequence.SelfTest(),gamepad=CalibratorGamepad.SelfTest();bool targets=CalibratorWindows.Allowed("Cyberpunk2077")&&CalibratorWindows.Allowed("Uncrashed-Win64-Shipping")&&!CalibratorWindows.Allowed("explorer");if(!targets)throw new Exception("Filtro de alvo falhou");int manualChecks=0,gameModes=0,hotkeysChecked=CalibratorWindow.HotkeySelfTest();Size size=CalibratorWindows.VideoSize(new Rectangle(0,0,3440,1440));if(size.Width!=1280||size.Height!=534)throw new Exception("Proporção de captura falhou");var crop=CalibratorWindows.CenterCrop(new Rectangle(0,0,3440,1440));if(crop!=new Rectangle(1240,450,960,540))throw new Exception("Recorte central falhou");if(CalibratorWindows.CenterCrop(new Rectangle(0,0,640,360))!=new Rectangle(0,0,640,360))throw new Exception("Recorte menor falhou");if(CalibratorWindows.CenterCrop(new Rectangle(-1920,0,1920,1080))!=new Rectangle(-1440,270,960,540))throw new Exception("Recorte em outro monitor falhou");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var window=new CalibratorWindow(true)){window.ShowInTaskbar=false;window.StartPosition=FormStartPosition.Manual;window.Location=new System.Drawing.Point(-30000,-30000);gameModes=window.ModeSelfTest();manualChecks=window.ManualSelfTest();int policy=window.PolicySelfTest();if(policy!=2)throw new Exception("Política de potência falhou");window.Show();Application.DoEvents();using(var bitmap=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(bitmap,new Rectangle(0,0,window.Width,window.Height));bitmap.Save(Path.Combine(args[1],"interface.png"),ImageFormat.Png);}using(var previewHud=new CalibratorHud()){for(int game=0;game<2;game++){string title=CalibratorWindow.StageTitle(game,3,13);if(title!=(game==0?"UNCRASHED — ETAPA 3 DE 13":"CYBERPUNK 2077 — ETAPA 3 DE 13"))throw new Exception("Identificação do jogo/etapa incorreta.");previewHud.UpdateFor(window.Handle,title,"Reposicione o drone. Aguardando F10 para continuar.");Application.DoEvents();using(var bitmap=new Bitmap(previewHud.Width,previewHud.Height)){previewHud.DrawToBitmap(bitmap,new Rectangle(0,0,previewHud.Width,previewHud.Height));bitmap.Save(Path.Combine(args[1],game==0?"hud-uncrashed.png":"hud-cyberpunk.png"),ImageFormat.Png);}}previewHud.Close();}window.Close();}CalibratorRuntime.WriteJson(Path.Combine(args[1],"resultado.json"),new{Passed=capture+sequence+gamepad+10+gameModes+hotkeysChecked+manualChecks,ManualCalibration=manualChecks,StageLabels=2,Hotkeys=hotkeysChecked,GameModes=gameModes,Capture=capture,Sequence=sequence,Gamepad=gamepad,RuntimeHardwareUsed=false,VirtualCreated=false,GameTouched=false,PreviewOnly=true});return 0;}
        if(args.Length==2&&args[0]=="--probe-physical"){using(var pad=CalibratorRuntime.Gamepad()){pad.OpenPhysical();var value=pad.ReadPhysical();CalibratorRuntime.WriteJson(args[1],new{PhysicalName=pad.PhysicalName,Connected=pad.Connected,Throttle=value.Throttle,Yaw=value.Yaw,Roll=value.Roll,Pitch=value.Pitch,VirtualCreated=pad.VirtualConnected,DriverInstalled=false,GameFilesChanged=false});}return 0;}
        if(args.Length==2&&args[0]=="--probe-bus"){using(var pad=CalibratorRuntime.Gamepad()){pad.ProbeBusOnly();CalibratorRuntime.WriteJson(args[1],new{DriverResponded=true,VirtualCreated=pad.VirtualConnected,ControllerInputSent=false,GameFilesChanged=false});}return 0;}
        if(args.Length==2&&args[0]=="--probe-windows"){var windows=new List<object>();for(int game=0;game<2;game++){IntPtr w=CalibratorWindows.FindGame(game);Rectangle area=CalibratorWindows.Area(w);windows.Add(new{Game=game==0?"Uncrashed":"Cyberpunk",PID=CalibratorWindows.Pid(w),Width=area.Width,Height=area.Height});}CalibratorRuntime.WriteJson(args[1],new{Windows=windows,FocusChanged=false,InputSent=false,ScreenshotTaken=false});return 0;}
        if(args.Length==2&&args[0]=="--probe-hotkeys"){var results=new List<object>();using(var window=new Form()){IntPtr handle=window.Handle;foreach(int key in new[]{10,11}){bool registered=CalibratorWindows.RegisterHotKey(handle,key,0x4000,(uint)(0x70+key-1));int error=registered?0:Marshal.GetLastWin32Error();if(registered)CalibratorWindows.UnregisterHotKey(handle,key);results.Add(new{Key="F"+key,Registered=registered,Error=error});}}CalibratorRuntime.WriteJson(args[1],new{Results=results,F12Attempted=false,GameInputSent=false,VirtualCreated=false});return 0;}
        if(args.Length!=0)throw new IOException("Argumento não reconhecido.");bool created;using(var mutex=new Mutex(true,"Local\\FPVCalibradorApp",out created)){if(!created){MessageBox.Show("O calibrador já está aberto.");return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new CalibratorWindow());}return 0;
    }catch(Exception ex){if(args.Length>1){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(args[1])));File.WriteAllText(args[1]+".error.txt",ex.ToString());}else MessageBox.Show(ex.Message,"Calibrador FPV");return 1;}}
}
